mapper.select:
select
a.period_id,
a.cron_expression,
a.remark,
a.update_time,
a.create_time
from t_period_model a
where 1 = 1
 and a.period_id = #{periodId, jdbcType=BIGINT}
 and a.cron_expression = #{cronExpression, jdbcType=VARCHAR}
 and a.remark = #{remark, jdbcType=VARCHAR}
 and a.update_time = #{updateTime, jdbcType=TIMESTAMP}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}

